package io.github.victorkolesnyk.hamir.data

import android.security.keystore.KeyGenParameterSpec
import android.security.keystore.KeyProperties
import io.github.victorkolesnyk.hamir.logic.BankKeyProvider
import java.security.KeyStore
import javax.crypto.KeyGenerator
import javax.crypto.SecretKey

/**
 * AES-256-GCM key in AndroidKeyStore (SPEC section 9). The key never leaves the keystore,
 * needs no user authentication and only accepts IVs generated by the cipher.
 * All APIs used here exist since API 23.
 */
class KeystoreKeyProvider : BankKeyProvider {

    @Synchronized
    override fun getOrCreateKey(): SecretKey {
        val keyStore = KeyStore.getInstance(PROVIDER)
        keyStore.load(null)
        val existing = keyStore.getKey(ALIAS, null)
        if (existing is SecretKey) return existing

        val spec = KeyGenParameterSpec.Builder(
            ALIAS,
            KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT,
        )
            .setKeySize(256)
            .setBlockModes(KeyProperties.BLOCK_MODE_GCM)
            .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)
            .setUserAuthenticationRequired(false)
            .build()
        val generator = KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES, PROVIDER)
        generator.init(spec)
        return generator.generateKey()
    }

    @Synchronized
    override fun deleteKey() {
        val keyStore = KeyStore.getInstance(PROVIDER)
        keyStore.load(null)
        if (keyStore.containsAlias(ALIAS)) keyStore.deleteEntry(ALIAS)
    }

    companion object {
        const val ALIAS = "hamir_bank_v1"
        private const val PROVIDER = "AndroidKeyStore"
    }
}
